\set on_error_stop on
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values('46500000-0000-4000-8000-000000000001','authenticated','authenticated','cloud-listing@example.test','{}','{}');
insert into public.platform_operators(user_id) values('46500000-0000-4000-8000-000000000001');
insert into public.workspaces(id,name) values('46500000-0000-4000-8000-000000000011','Cloud-Inserate');
insert into public.workspace_members(workspace_id,user_id,role) values('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000001','owner');
insert into public.marketplace_connections(id,workspace_id,display_name,execution_mode,status,external_account_id) values('46500000-0000-4000-8000-000000000021','46500000-0000-4000-8000-000000000011','Cloud','cloud','connected','46501');
insert into public.marketplace_browser_profiles(workspace_id,connection_id,provider_profile_id) values('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021','cloud-listing-profile');
create temporary table cloud_listing_context(draft jsonb,job jsonb,claim jsonb,old_claim jsonb,result jsonb);
grant all on cloud_listing_context to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claim.sub','46500000-0000-4000-8000-000000000001',true);
select public.marketplace_approve_listings('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021','46501');
insert into cloud_listing_context(draft) select public.marketplace_create_listing_draft('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021','{"title":"Cloud-Test","description":"Gebraucht","priceCents":1200,"currency":"EUR","categoryId":1223,"conditionId":2,"packageSizeId":2}');
reset role;
insert into public.marketplace_listing_images(workspace_id,draft_id,storage_path,file_name,mime_type,byte_size,state,created_by)
select '46500000-0000-4000-8000-000000000011',(draft->>'id')::bigint,'46500000-0000-4000-8000-000000000011/'||(draft->>'id')||'/46500000-0000-4000-8000-000000000041.jpg','test.jpg','image/jpeg',123,'ready','46500000-0000-4000-8000-000000000001' from cloud_listing_context;
update public.marketplace_listing_drafts set image_ids=array[(select id from public.marketplace_listing_images where created_by='46500000-0000-4000-8000-000000000001')] where id=(select (draft->>'id')::bigint from cloud_listing_context);
insert into storage.objects(bucket_id,name,metadata) select 'marketplace-listing-media',storage_path,'{"size":123,"mimetype":"image/jpeg"}' from public.marketplace_listing_images where created_by='46500000-0000-4000-8000-000000000001';
set local role authenticated;
savepoint relist_workflow;
update cloud_listing_context set job=public.marketplace_enqueue_listing(draft->>'id',1,'publish','46500000-0000-4000-8000-000000000031',false);
select throws_ok($$select public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061')$$,'42501',null,'Clients können keinen Cloud-Inseratversuch übernehmen');
set local role service_role;
select public.marketplace_worker_claim('46500000-0000-4000-8000-000000000051');
select is(public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',2,'46500000-0000-4000-8000-000000000061'),null::jsonb,'Falsche Worker-Epoche übernimmt keinen Auftrag');
update cloud_listing_context set claim=public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061');
select is((select claim->>'jobId' from cloud_listing_context),(select job->>'id' from cloud_listing_context),'Eigene Inseratfreigabe genügt ohne Cloud-Nachrichtenrechte');
select is((select jsonb_typeof(claim->'jobId') from cloud_listing_context),'string','Cloud-Auftragskennung bleibt verlustfreier Text');
select is((select provider_profile_id from public.marketplace_browser_sessions where public_id=(select (claim->>'sessionId')::uuid from cloud_listing_context)),'cloud-listing-profile','Übernahme reserviert ausschließlich das freigegebene Profil');
select is(public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061'),null::jsonb,'Aktiver Browser wird nicht doppelt reserviert');
update cloud_listing_context set old_claim=claim;
reset role;
update public.marketplace_listing_jobs set lease_expires_at=clock_timestamp()-interval '1 second';
update public.marketplace_browser_sessions set state='stopping',expires_at=clock_timestamp()-interval '1 second' where state='active';
set local role service_role;
select is(public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061'),null::jsonb,'Abgelaufene Vorbereitung wartet auf bestätigten physischen Browserstopp');
select is((select state from public.marketplace_listing_jobs),'claimed','Browserablauf allein gibt die Vorbereitung nicht frei');
reset role;
update public.marketplace_browser_sessions set state='closed',provider_stopped_at=clock_timestamp() where state='stopping';
set local role service_role;
update cloud_listing_context set claim=public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061');
select isnt((select claim->>'claimToken' from cloud_listing_context),(select old_claim->>'claimToken' from cloud_listing_context),'Nach physischem Stopp erhält Vorbereitung einen neuen Versuch');
select throws_ok($$select public.marketplace_cloud_listing_begin('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (old_claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1)$$,'42501',null,'Der alte Browser darf nach Neuübernahme nicht beginnen');
select is(public.marketplace_cloud_listing_check('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',2)->>'active','false','Falsche Worker-Epoche erhält keine Schreibfreigabe');
savepoint wrong_profile;
reset role;
update public.marketplace_browser_sessions set provider_profile_id='other-profile' where state='active';
set local role service_role;
select is(public.marketplace_cloud_listing_check('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1)->>'active','false','Fremdes Browserprofil kann keinen Inseratversuch ausführen');
rollback to wrong_profile;
select lives_ok($$select public.marketplace_cloud_listing_begin('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1)$$,'Cloud-Schreibbeginn wird einmalig angenommen');
select throws_ok($$select public.marketplace_cloud_listing_begin('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1)$$,'42501',null,'Cloud-Schreibbeginn wird nie wiederholt');
reset role;
update public.marketplace_listing_jobs set lease_expires_at=clock_timestamp()-interval '1 second';
set local role authenticated;
select is(public.marketplace_read_listing_jobs('46500000-0000-4000-8000-000000000011')->'items'->0->>'state','outcome_unknown','Verlauf erkennt Cloud-Ausfall auch ohne laufenden Worker');
set local role service_role;
reset role;
update public.marketplace_browser_sessions set state='closed',provider_stopped_at=clock_timestamp() where state='active';
set local role service_role;
select is(public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061'),null::jsonb,'Nach begonnenem Schreiben wird auch nach Browserstopp kein zweiter Versuch erzeugt');
update cloud_listing_context set result=jsonb_build_object('outcome','confirmed','action','publish','externalId','46502','externalAccountId','46501','providerState','processing','verifiedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
select throws_ok($$select public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',2,(select result from cloud_listing_context))$$,'42501',null,'Ein Ergebnis ist an die ursprüngliche Worker-Epoche gebunden');
reset role;
update public.marketplace_worker_runtime set expires_at=clock_timestamp()-interval '1 second' where id=1;
delete from public.marketplace_connections where id='46500000-0000-4000-8000-000000000021';
set constraints all immediate;
set local role service_role;
select lives_ok($$select public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1,(select result from cloud_listing_context))$$,'Später Beleg bleibt nach Workerablauf und Kontolöschung dem ursprünglichen Versuch zugeordnet');
select lives_ok($$select public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1,(select result from cloud_listing_context))$$,'Identischer später Cloud-Beleg bleibt idempotent');
select is((select provider_state from public.marketplace_listing_jobs),'processing','Anbieterprüfung wird getrennt von aktiver Veröffentlichung gespeichert');
-- Der feste Termin betrifft nur die Veröffentlichung, nicht die Löschung.
rollback to relist_workflow;
reset role;
update public.marketplace_listing_drafts set relist_external_id='98765' where id=(select (draft->>'id')::bigint from cloud_listing_context);
insert into public.marketplace_account_entries(workspace_id,connection_id,kind,external_id,body) values('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021','publication','98765','{"title":"Original","publicationState":"active"}');
set local role authenticated;
update cloud_listing_context set job=public.marketplace_enqueue_relisting(draft->>'id',1,'46500000-0000-4000-8000-000000000071',false,clock_timestamp()+interval '1 hour','Europe/Berlin');
set local role service_role;
select public.marketplace_worker_claim('46500000-0000-4000-8000-000000000051');
update cloud_listing_context set claim=public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061');
select is((select claim->'snapshot'->>'relistStage' from cloud_listing_context),'delete','Geplantes Relisting löscht sofort, obwohl die Veröffentlichung erst später fällig ist');
select lives_ok($$select public.marketplace_cloud_listing_begin('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1)$$,'Löschphase darf vor dem Veröffentlichungstermin beginnen');
update cloud_listing_context set result=jsonb_build_object('outcome','relisting_deleted','externalId','98765','externalAccountId','46501','verifiedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
select throws_ok($$select public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1,(select result||'{"externalId":"99999"}'::jsonb from cloud_listing_context))$$,'22023',null,'Ein Löschbeleg für eine andere Quelle wird verworfen');
update cloud_listing_context set job=public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',job->>'id',(claim->>'claimToken')::uuid,'46500000-0000-4000-8000-000000000051',1,result);
select is((select job->>'state' from cloud_listing_context),'queued','Bestätigte Löschung hinterlässt einen wartenden Auftrag');
select ok((select job->>'relistDeletedAt' is not null from cloud_listing_context),'Löschbeleg bleibt dauerhaft am Entwurf erhalten');
select lives_ok($$select public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1,(select result from cloud_listing_context))$$,'Wiederholte Löschbestätigung verändert den Termin nicht');
reset role;
update public.marketplace_browser_sessions set state='closed',provider_stopped_at=clock_timestamp() where state='active';
set local role service_role;
select is(public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061'),null::jsonb,'Vor dem festen Termin wird nicht veröffentlicht');
set local role authenticated;
select is(jsonb_array_length(public.marketplace_read_relisting_plans('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021')->'items'),1,'Die gelöschte Quelle bleibt als Planung im Kleiderschrank sichtbar');
update cloud_listing_context set job=public.marketplace_edit_relisting_plan(job->>'id',(job->>'version')::bigint,true);
select is((select job->>'errorCode' from cloud_listing_context),'editing','Bearbeitung pausiert die Veröffentlichung');
select throws_ok($$select public.marketplace_edit_relisting_plan((select job->>'id' from cloud_listing_context),1,false)$$,'40001',null,'Veraltete Bearbeitungskennung kann eine Planung nicht fortsetzen');
update cloud_listing_context set job=public.marketplace_edit_relisting_plan(job->>'id',(job->>'version')::bigint,false);
select is((select job->>'state' from cloud_listing_context),'queued','Abbrechen der Bearbeitung setzt den ursprünglichen Auftrag fort');
update cloud_listing_context set job=public.marketplace_edit_relisting_plan(job->>'id',(job->>'version')::bigint,true);
update cloud_listing_context set draft=public.marketplace_save_listing_draft(draft->>'id',1,'{"title":"Geänderte Jacke","description":"Gebraucht","priceCents":1900,"currency":"EUR","categoryId":1223,"conditionId":2,"packageSizeId":2}','46500000-0000-4000-8000-000000000021');
update cloud_listing_context set old_claim=job,job=public.marketplace_enqueue_relisting(draft->>'id',(draft->>'revision')::bigint,'46500000-0000-4000-8000-000000000072',false,clock_timestamp()+interval '2 hours','Europe/Berlin',0,job->>'id',(job->>'version')::bigint);
select is((select job->>'itemTitle' from cloud_listing_context),'Geänderte Jacke','Gespeicherte Änderungen ersetzen die alte Aufnahme');
select is((select job->>'replacesJobId' from cloud_listing_context),(select old_claim->>'id' from cloud_listing_context),'Ersatz und Abbruch sind miteinander verknüpft');
reset role;
update public.marketplace_listing_jobs set relist_publish_at=clock_timestamp()-interval '1 second' where id=(select (job->>'id')::bigint from cloud_listing_context);
set local role service_role;
update cloud_listing_context set claim=public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061');
select is((select claim->'snapshot'->>'relistStage' from cloud_listing_context),'publish','Geänderte Planung veröffentlicht ohne einen zweiten Löschauftrag');
select is((select claim->'snapshot'->'content'->>'priceCents' from cloud_listing_context),'1900','Worker verwendet den geänderten Preis');
set local role authenticated;
select throws_ok($$select public.marketplace_edit_relisting_plan((select job->>'id' from cloud_listing_context),(select version from public.marketplace_listing_jobs where id=(select (job->>'id')::bigint from cloud_listing_context)),true)$$,'22023',null,'Eine bereits übernommene Veröffentlichung kann nicht mehr bearbeitet werden');

-- Relative Wartezeit beginnt nach dem Löschbeleg.
rollback to relist_workflow;
reset role;
update public.marketplace_listing_drafts set relist_external_id='98765' where id=(select (draft->>'id')::bigint from cloud_listing_context);
insert into public.marketplace_account_entries(workspace_id,connection_id,kind,external_id,body) values('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021','publication','98765','{"title":"Original","publicationState":"active"}');
set local role authenticated;
update cloud_listing_context set job=public.marketplace_enqueue_relisting(draft->>'id',1,'46500000-0000-4000-8000-000000000073',false,null,null,180);
select is((select job->>'scheduledAt' from cloud_listing_context),null,'Relative Planung legt noch keinen Termin vor der Löschung fest');
select throws_ok($$select public.marketplace_enqueue_relisting((select draft->>'id' from cloud_listing_context),1,'46500000-0000-4000-8000-000000000073',false,null,null,60)$$,'23505',null,'Dieselbe Auftragskennung kann die Wartezeit nicht nachträglich verändern');
set local role service_role;
select public.marketplace_worker_claim('46500000-0000-4000-8000-000000000051');
update cloud_listing_context set claim=public.marketplace_cloud_listing_claim('46500000-0000-4000-8000-000000000051',1,'46500000-0000-4000-8000-000000000061');
select public.marketplace_cloud_listing_begin('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',(select job->>'id' from cloud_listing_context),(select (claim->>'claimToken')::uuid from cloud_listing_context),'46500000-0000-4000-8000-000000000051',1);
update cloud_listing_context set result=jsonb_build_object('outcome','relisting_deleted','externalId','98765','externalAccountId','46501','verifiedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
update cloud_listing_context set job=public.marketplace_cloud_listing_finish('46500000-0000-4000-8000-000000000011','46500000-0000-4000-8000-000000000021',job->>'id',(claim->>'claimToken')::uuid,'46500000-0000-4000-8000-000000000051',1,result);
select ok((select (job->>'scheduledAt')::timestamptz between clock_timestamp()+interval '179 seconds' and clock_timestamp()+interval '181 seconds' from cloud_listing_context),'Drei Minuten Wartezeit werden ab bestätigter Löschung berechnet');
select * from finish();
rollback;
